using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // EF Core 9 renamed "Discriminator" to "$type". Revert to old name
            // so existing 500K documents remain readable without migration.
            entity.HasDiscriminator<string>("Discriminator");

            // EF Core 9 changed id format from "Product|123" to "Product|<guid>".
            // Use IdProperty with value generation to keep the legacy format.
            entity.HasKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();

            entity.HasIndex(p => p.Sku);
        });
    }
}

class Product { public int Id { get; set; } public string Sku { get; set; } }

